    private async Task<List<ShiftHandover>> LoadHandoversAsync(int limit, CancellationToken ct)
    {
        var rows = await Query("SELECT TOP(@limit) * FROM nurse.ShiftHandovers WHERE HospitalId=@h AND BranchId=@b ORDER BY CreatedAtUtc DESC", r => new { Id = G(r, "Id"), From = G(r, "FromNurse"), ToId = G(r, "ToNurseId"), To = S(r, "ToNurseName"), Summary = S(r, "Summary"), Status = S(r, "Status"), At = T(r, "CreatedAtUtc"), AckAt = TN(r, "AcknowledgedAtUtc"), AckBy = GN(r, "AcknowledgedBy"), Version = L(r, "Version") }, H, Branch, ("limit", limit));
        var result = new List<ShiftHandover>();
        foreach (var row in rows) { var patients = await Query("SELECT PatientId FROM nurse.HandoverPatients WHERE HandoverId=@id", r => G(r, "PatientId"), ("id", row.Id)); result.Add(new ShiftHandover(row.Id, row.From, row.To, row.Summary, patients, row.Status, row.At, row.AckAt, row.AckBy, row.Version) { ToNurseId = row.ToId }); }
        return result;
    }
    private async Task<List<Dispense>> LoadDispensesAsync(int limit, CancellationToken ct)
    {
        var rows = await Query("SELECT TOP(@limit) * FROM pharmacy.Dispenses WHERE HospitalId=@h AND BranchId=@b ORDER BY CreatedAtUtc DESC", r => new { Id = G(r, "Id"), Number = S(r, "Number"), Kind = S(r, "Kind"), Patient = G(r, "PatientId"), Encounter = GN(r, "EncounterId"), Admission = GN(r, "AdmissionId"), Key = S(r, "IdempotencyKey"), Hash = S(r, "RequestHash"), At = T(r, "CreatedAtUtc"), By = G(r, "CreatedBy") }, H, Branch, ("limit", limit));
        var result = new List<Dispense>(); foreach (var row in rows) result.Add(await LoadDispenseChildren(row.Id, row.Number, row.Kind, row.Patient, row.Encounter, row.Admission, row.Key, row.Hash, row.At, row.By, ct)); return result;
    }
    private async Task<Dispense> LoadDispenseChildren(Guid id, string number, string kind, Guid patient, Guid? encounter, Guid? admission, string key, string hash, DateTimeOffset at, Guid by, CancellationToken ct)
    {
        var lines = await Query("SELECT Id,MedicineId,Name,Quantity FROM pharmacy.DispenseLines WHERE DispenseId=@id ORDER BY Name", r => new { Id = G(r, "Id"), Med = G(r, "MedicineId"), Name = S(r, "Name"), Qty = D(r, "Quantity") }, ("id", id));
        var result = new List<DispenseLine>();
        foreach (var line in lines) { var batches = await Query("SELECT BatchId,BatchNumber,Quantity FROM pharmacy.DispenseBatches WHERE DispenseLineId=@id", r => new BatchAllocation(G(r, "BatchId"), S(r, "BatchNumber"), D(r, "Quantity")), ("id", line.Id)); result.Add(new DispenseLine(line.Med, line.Name, line.Qty, batches)); }
        return new Dispense(id, number, kind, patient, encounter, admission, result, key, at, by) { RequestHash = hash };
    }
    public Task<bool> HasActiveAdmissionsAsync(CancellationToken ct) => Query("SELECT COUNT(1) FROM ipd.Admissions WHERE HospitalId=@h AND BranchId=@b AND Status='Active'", r => Convert.ToInt32(r[0]), H, Branch).ContinueWith(t => t.Result[0] > 0, ct);
    public async Task<Bed?> FindBedAsync(Guid id, CancellationToken ct) => (await Query($"SELECT {BedColumns} FROM ipd.Beds WHERE HospitalId=@h AND BranchId=@b AND Id=@id", MapBed, H, Branch, ("id", id))).FirstOrDefault();
    public async Task UpdateBedAsync(Bed bed, CancellationToken ct) { if (await Execute("UPDATE ipd.Beds SET Status=@status,Notes=@notes,Version=@new WHERE Id=@id AND HospitalId=@h AND BranchId=@b AND Version=@old", ("status", bed.Status), ("notes", bed.Notes), ("new", bed.Version), ("id", bed.Id), H, Branch, ("old", bed.Version - 1)) != 1) throw Conflict(); }
    public async Task<Admission?> FindAdmissionAsync(Guid id, CancellationToken ct) => (await Query($"SELECT {AdmissionColumns} FROM ipd.Admissions WHERE HospitalId=@h AND BranchId=@b AND Id=@id", MapAdmission, H, Branch, ("id", id))).FirstOrDefault();
    public async Task<Admission?> FindActiveAdmissionByPatientAsync(Guid patientId, CancellationToken ct) => (await Query($"SELECT {AdmissionColumns} FROM ipd.Admissions WHERE HospitalId=@h AND PatientId=@p AND Status='Active'", MapAdmission, H, ("p", patientId))).FirstOrDefault();
