    public Task InsertAdmissionAsync(Admission a, CancellationToken ct) => Execute("INSERT INTO ipd.Admissions(Id,HospitalId,BranchId,Number,PatientId,BedId,DoctorId,Status,Reason,AdmittedAtUtc,CreatedBy,Version) VALUES(@id,@h,@b,@number,@patient,@bed,@doctor,@status,@reason,@at,@actor,1)", ("id", a.Id), H, Branch, ("number", a.Number), ("patient", a.PatientId), ("bed", a.BedId), ("doctor", a.DoctorId), ("status", a.Status), ("reason", a.Reason), ("at", a.AdmittedAt.UtcDateTime), ("actor", scope.Actor.Id));
