    public async Task InsertDispenseAsync(Dispense d, CancellationToken ct) { await Execute("INSERT INTO pharmacy.Dispenses(Id,HospitalId,BranchId,Number,Kind,PatientId,EncounterId,AdmissionId,IdempotencyKey,RequestHash,CreatedAtUtc,CreatedBy) VALUES(@id,@h,@b,@number,@kind,@patient,@encounter,@admission,@key,@hash,@at,@actor)", ("id", d.Id), H, Branch, ("number", d.Number), ("kind", d.Kind), ("patient", d.PatientId), ("encounter", d.EncounterId), ("admission", d.AdmissionId), ("key", d.IdempotencyKey), ("hash", d.RequestHash), ("at", d.CreatedAt.UtcDateTime), ("actor", d.CreatedBy)); foreach (var line in d.Lines) { var lineId = Guid.NewGuid(); await Execute("INSERT INTO pharmacy.DispenseLines(Id,HospitalId,DispenseId,MedicineId,Name,Quantity) VALUES(@id,@h,@dispense,@medicine,@name,@qty)", ("id", lineId), H, ("dispense", d.Id), ("medicine", line.MedicineId), ("name", line.Name), ("qty", line.Quantity)); foreach (var batch in line.Batches) await Execute("INSERT INTO pharmacy.DispenseBatches(DispenseLineId,BatchId,HospitalId,BatchNumber,Quantity) VALUES(@line,@batch,@h,@number,@qty)", ("line", lineId), ("batch", batch.BatchId), H, ("number", batch.BatchNumber), ("qty", batch.Quantity)); } }
